import { expect, expectStatus, test } from "../../fixtures";

test("an admin approves a vendor's w9 extraction and the vendor stays in the review queue", { tag: "@LIF-12" }, async ({ factory, apiAs }) => {
  // Arrange
  const { vendor, documents, extractions } = await factory.vendorInReview();
  const admin = await apiAs("admin");
  const w9 = extractions.w9;

  // Act
  const decision = await admin.post(`/api/extractions/${w9.id}/decision`, {
    data: { decision: "approve" },
  });

  // Assert
  const decided = await expectStatus<{ id: string; status: string }>(decision, 200);
  expect(decided.id).toBe(w9.id);
  expect(decided.status).toBe("approved");

  // The stored outcome, not just the echoed response. The extraction is read through its document.
  const stored = await factory.extraction(documents.w9.id, "admin");
  expect(stored.status).toBe("approved");

  // The queue still lists the vendor, since its other extractions await review.
  const queue = await expectStatus<Array<{ vendor_id: string }>>(
    await admin.get("/api/review-queue"),
    200,
  );
  expect(queue.map((item) => item.vendor_id)).toContain(vendor.id);
});
